import{_ as d,o as r,c as a,a2 as o}from"./chunks/framework.DSoq407f.js";const c=JSON.parse('{"title":"名词解释","description":"","frontmatter":{},"headers":[],"relativePath":"guide/glossary.md","filePath":"guide/glossary.md","lastUpdated":1786543008000}'),e={name:"guide/glossary.md"};function n(s,t,h,g,l,i){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="名词解释" tabindex="-1">名词解释 <a class="header-anchor" href="#名词解释" aria-label="Permalink to &quot;名词解释&quot;">​</a></h1><p>阅读文档前，先熟悉这些核心概念。</p><h2 id="平台与适配器" tabindex="-1">平台与适配器 <a class="header-anchor" href="#平台与适配器" aria-label="Permalink to &quot;平台与适配器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名词</th><th>含义</th></tr></thead><tbody><tr><td><strong>平台</strong></td><td>即时通讯服务，如 QQ 官方、Telegram、Discord 等</td></tr><tr><td><strong>适配器（Adapter）</strong></td><td>连接某个平台的桥梁，负责把平台事件转成统一格式、把统一消息发回平台</td></tr><tr><td><strong>连接模式</strong></td><td>适配器接入平台的方式：Webhook 回调、正向 WebSocket、反向 WebSocket、长轮询等</td></tr></tbody></table><h2 id="机器人与租户" tabindex="-1">机器人与租户 <a class="header-anchor" href="#机器人与租户" aria-label="Permalink to &quot;机器人与租户&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名词</th><th>含义</th></tr></thead><tbody><tr><td><strong>机器人（Bot）</strong></td><td>一个具体的机器人实例，绑定到一个平台账号，归属于某个用户</td></tr><tr><td><strong>租户 / 用户</strong></td><td>平台上的一个客户，拥有自己的机器人、订阅、余额</td></tr><tr><td><strong>绑定（Binding）</strong></td><td>机器人与插件的关联关系——一个机器人装了哪些插件、各自的开关与设置</td></tr></tbody></table><h2 id="插件与-xubp" tabindex="-1">插件与 XUBP <a class="header-anchor" href="#插件与-xubp" aria-label="Permalink to &quot;插件与 XUBP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名词</th><th>含义</th></tr></thead><tbody><tr><td><strong>插件（Plugin）</strong></td><td>提供某项功能的可安装模块，如签到、积分商城、视频解析</td></tr><tr><td><strong>XUBP</strong></td><td>Xiaoyi Universal Bot Protocol，V3 的通用插件开发协议，让插件跨平台通用</td></tr><tr><td><strong>事件（Event）</strong></td><td>平台发生的事情（收到消息、被加群等），标准化后传给插件</td></tr><tr><td><strong>钩子（Hook）</strong></td><td>插件里定义的特定函数（如 <code>handle_event</code>），框架在对应时机自动调用</td></tr><tr><td><strong>上下文（Context）</strong></td><td>钩子函数收到的对象，包含事件数据、配置、发送消息的方法等</td></tr><tr><td><strong>data_store</strong></td><td>插件的数据存储接口，按 <code>插件 + 用户 + 机器人</code> 自动隔离</td></tr><tr><td><strong>拦截器</strong></td><td>一种特殊插件，在消息发出前 / 发出后介入，可修改或阻断消息</td></tr></tbody></table><h2 id="商业化" tabindex="-1">商业化 <a class="header-anchor" href="#商业化" aria-label="Permalink to &quot;商业化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名词</th><th>含义</th></tr></thead><tbody><tr><td><strong>订阅（Subscription）</strong></td><td>用户购买的服务套餐，决定可用机器人数、插件数等配额</td></tr><tr><td><strong>套餐（Plan）</strong></td><td>订阅的规格，分月付 / 年付 / 永久 / 自定义</td></tr><tr><td><strong>卡密（Card Key）</strong></td><td>可兑换套餐、余额或插件的兑换码</td></tr><tr><td><strong>余额</strong></td><td>用户账户里的预存金额，可购买插件、续订</td></tr><tr><td><strong>开发者分成</strong></td><td>客户购买付费插件时，开发者获得的收益比例</td></tr></tbody></table><h2 id="权限与角色" tabindex="-1">权限与角色 <a class="header-anchor" href="#权限与角色" aria-label="Permalink to &quot;权限与角色&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名词</th><th>含义</th></tr></thead><tbody><tr><td><strong>RBAC</strong></td><td>基于角色的权限控制</td></tr><tr><td><strong>管理后台</strong></td><td>平台运营方使用的管理界面</td></tr><tr><td><strong>用户控制台</strong></td><td>租户使用的自助界面</td></tr><tr><td><strong>开发者中心</strong></td><td>插件开发者上传、管理插件的界面</td></tr><tr><td><strong>审计日志</strong></td><td>记录关键操作（谁、何时、做了什么）的日志</td></tr></tbody></table><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名词</th><th>含义</th></tr></thead><tbody><tr><td><strong>Open API</strong></td><td>对外开放的 HTTP API，凭 API Key 调用，用于二次集成</td></tr><tr><td><strong>WebUI</strong></td><td>插件自带的管理界面，在机器人配置页内嵌展示</td></tr><tr><td><strong>授权码（authcode）</strong></td><td>域名绑定授权的凭证，安装时自动获取或手动填写</td></tr></tbody></table>',14)])])}const u=d(e,[["render",n]]);export{c as __pageData,u as default};
